using System.Windows;using System.Windows.Controls;using LibraryManager.Services;using LibraryManager.Models;namespace LibraryManager.Views;public partial class UnpaidFinesView:UserControl{LoanService svc=new();DataGrid grid;public UnpaidFinesView(){InitializeComponent();var p=VH.Page(Root,"جریمه‌های پرداخت‌نشده");grid=VH.Table(p,svc.Unpaid());p.Children.Add(VH.Btn("ثبت پرداخت جریمه",(s,e)=>{if(grid.SelectedItem is Loan l&&PaymentDialog.ShowPayment("پرداخت جریمه: "+l.FineAmount)){new PaymentService().PayFine(l.Id,PaymentDialog.Method);grid.ItemsSource=svc.Unpaid();}}));}}